def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()  # {key: (value, write_time)}
    results = []

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op

            # Remove expired entries before modifying cache
            expired_keys = [k for k, (_, write_time) in cache.items() if write_time + ttl <= t]
            for k in expired_keys:
                del cache[k]

            # If key already exists, remove it first (will re-add at end)
            if key in cache:
                del cache[key]
            # If cache is at capacity, evict LRU
            elif len(cache) >= capacity:
                cache.popitem(last=False)

            # Add the new entry (most recently used)
            cache[key] = (value, t)

        elif op[0] == 'get':
            _, t, key = op

            # Remove expired entries
            expired_keys = [k for k, (_, write_time) in cache.items() if write_time + ttl <= t]
            for k in expired_keys:
                del cache[k]

            # Get the value
            if key in cache:
                value, write_time = cache[key]
                # Move to end (most recently used)
                del cache[key]
                cache[key] = (value, write_time)
                results.append(value)
            else:
                results.append(-1)

    return results

